    lines=f.read().splitlines()
# Find AHU02 block and feeds
for i,line in enumerate(lines):
    if 'feeds' in line:
        # print block
        j=i
        end=i
        while end<len(lines) and ' .\n' not in lines[end]:
            end+=1
        for k in range(max(0,i-1), min(len(lines), end+2)):
            print(lines[k])
        print('---')

